// Secrets at rest: AES-256-GCM with a master key from APP_SECRET or /config/.secret_key (0600).
// Each value is bound to its setting name (AAD), so ciphertexts can't be swapped between keys.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { CONFIG_DIR } from './config.js';
import { getSetting, randomToken, setSetting } from './db.js';

export const SECRET_KEYS = ['lidarr_api_key', 'ai_api_key', 'lastfm_api_key', 'api_key', 'webhook_secret', 'session_secret'] as const;
export type SecretKey = (typeof SECRET_KEYS)[number];

/** Generated by Spin Seek itself: safe to regenerate if they can't be decrypted. */
const AUTO_SECRETS: Partial<Record<SecretKey, number>> = { api_key: 20, webhook_secret: 16, session_secret: 32 };

const PREFIX = 'enc:v1:';
export const KEY_FILE = path.join(CONFIG_DIR, '.secret_key');

function loadMasterKey(): Buffer {
  const fromEnv = process.env.APP_SECRET?.trim();
  if (fromEnv) {
    if (fromEnv.length < 16) console.warn('[secrets] APP_SECRET is short; use at least 32 random characters.');
    return crypto.scryptSync(fromEnv, 'spinseek:app-secret:v1', 32);
  }
  if (fs.existsSync(KEY_FILE)) {
    try {
      fs.chmodSync(KEY_FILE, 0o600);
    } catch {
      // not supported on this filesystem (e.g. Windows)
    }
    const buf = Buffer.from(fs.readFileSync(KEY_FILE, 'utf8').trim(), 'hex');
    if (buf.length !== 32) throw new Error(`${KEY_FILE} is corrupt (expected 64 hex characters). Restore it from a backup.`);
    return buf;
  }
  const key = crypto.randomBytes(32);
  fs.writeFileSync(KEY_FILE, key.toString('hex'), { mode: 0o600, flag: 'wx' });
  console.log(`[secrets] generated a new encryption key at ${KEY_FILE}`);
  return key;
}

const masterKey = loadMasterKey();
const cache = new Map<SecretKey, string>();

function encrypt(name: SecretKey, plain: string): string {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', masterKey, iv);
  cipher.setAAD(Buffer.from(name));
  const ct = Buffer.concat([cipher.update(plain, 'utf8'), cipher.final()]);
  return `${PREFIX}${iv.toString('base64')}:${cipher.getAuthTag().toString('base64')}:${ct.toString('base64')}`;
}

function decrypt(name: SecretKey, stored: string): string {
  const [iv, tag, ct] = stored.slice(PREFIX.length).split(':');
  if (!iv || !tag || ct === undefined) throw new Error('malformed ciphertext');
  const decipher = crypto.createDecipheriv('aes-256-gcm', masterKey, Buffer.from(iv, 'base64'));
  decipher.setAAD(Buffer.from(name));
  decipher.setAuthTag(Buffer.from(tag, 'base64'));
  return Buffer.concat([decipher.update(Buffer.from(ct, 'base64')), decipher.final()]).toString('utf8');
}

export function getSecret(name: SecretKey): string {
  const hit = cache.get(name);
  if (hit !== undefined) return hit;
  const raw = getSetting(name);
  if (!raw) return '';
  if (!raw.startsWith(PREFIX)) return raw; // legacy plaintext (migrated at startup)
  try {
    const value = decrypt(name, raw);
    cache.set(name, value);
    return value;
  } catch {
    return '';
  }
}

export function setSecret(name: SecretKey, value: string): void {
  const v = value.trim();
  setSetting(name, v ? encrypt(name, v) : '');
  cache.set(name, v);
}

export function hasSecret(name: SecretKey): boolean {
  return getSecret(name).length > 0;
}

/** Encrypt legacy plaintext values, detect undecryptable ones, and create auto-managed secrets. */
function initSecrets(): void {
  for (const name of SECRET_KEYS) {
    const raw = getSetting(name);
    if (!raw) continue;
    if (!raw.startsWith(PREFIX)) {
      setSecret(name, raw);
      continue;
    }
    try {
      cache.set(name, decrypt(name, raw));
    } catch {
      if (AUTO_SECRETS[name]) {
        console.warn(`[secrets] could not decrypt ${name}; generating a new one`);
        setSetting(name, '');
      } else {
        console.error(
          `[secrets] could not decrypt ${name}: was ${KEY_FILE} deleted or APP_SECRET changed? Re-enter it in Settings.`,
        );
      }
    }
  }
  for (const [name, bytes] of Object.entries(AUTO_SECRETS) as [SecretKey, number][]) {
    if (!getSecret(name)) setSecret(name, randomToken(bytes));
  }
}

initSecrets();
